# -*- coding: utf-8 -*-
import json, os, sys
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from ai_trader.journal import Journal
L = json.loads(r'''["=== 一、动机 ===","","第 101 轮偶然发现 test_first_live_trade.py 的 docstring 写着","「买入前 _equity_stale 拒绝入场」，而整个文件里 _equity_stale 只出现在那句 docstring 中。","清单上划了勾，实际没做。","","这类问题比「没写测试」更危险：它让人以为这里有保护。","所以这轮不靠下次运气好再撞见一个，直接做成机械扫描。","","=== 二、扫描做法 ===","","1) 用 AST 把每个测试文件的 docstring 和真实代码分开；","2) 从 docstring 里抽出「看起来是代码标识符」的词；","3) 检查该词是否出现在任意测试文件的真实代码里；","4) 只保留「只在 docstring 里出现」的，再与真实行覆盖率交叉验证。","","=== 三、第一版扫描器自己撒了谎 ===","","第一版报出 32 个 A 档候选。看着像发现了一批系统性谎报——但大部分是我的工具在撒谎。","找到三个假阳性来源，每一个都写进了工具头部：","","1) 函数的 def 行在 import 时就执行了","   后果：只要模块被 import，任何函数都显得「测过」。","2) 同名标识符跨模块冲突","   klines 在 rest.py / trend.py / feed.py 各有一份，互不相干。","3) docstring 提到名字是为了说明它【没被调用】","   把有价值的文档当成谎报。","","第 1 条最要命：我原来按「该标识符有任意一行被执行」判，","于是 21 个其实被测过的机制被算成假阳性放过去。","改成只统计使用点（调用/属性读写/变量引用，显式排除 def 行和 import 行）之后才勉强可信。","","=== 四、交叉验证后的结论：真阳性 0 个 ===","","只剩 3 个候选，逐一核实全部是假阳性：","","  ERROR             散文里的词。docstring 原文「日志里只有几行 critical，没有 ERROR 循环」；","                    源码匹配到的是 aiohttp.WSMsgType.ERROR","  check_risk_state  假阳性类型 3。docstring 在说明「趋势分支不调用它」，是准确的文档","  klines            假阳性类型 2。测试针对 trend.py 的种子路径，","                    未执行的是 feed.py:127 的 REST 兜底","","也就是说：_equity_stale 那一个是孤例，不是普遍现象。","这个负结果和正结果一样值钱——它把「要不要再花一轮重跑这个审计」的答案固定下来了。","","=== 五、留下来的工具和它的限度 ===","","tools/docclaim.py。用法：","  AI_COV=1 AI_COV_OUT=tools/_cov.json python -m pytest tests -q","  python tools/docclaim.py tools/_cov.json","","工具头部写清了三个假阳性来源和本轮的真阳性数（0）。","输出最后一行是「候选不等于结论，必须逐个核实」","——因为我已经被自己的第一版骗过一次。","","一条方法结论：","docstring 扫描只能产生假设，覆盖率才是验证。单独用任何一个都会撒谎。","","=== 六、验证 ===","","本轮没有改任何生产代码，也没有改任何测试——只新增一个审计工具和这段记录。","覆盖率数据用第 100 轮同一条命令重跑（499 条测试，全绿）。","","账户仍未到账（现货 USDT = 0）。"]''')
meta = json.loads(r'''{"round":102,"theme":"把「docstring 撒谎」做成机械扫描——结论是只有那一个","motivation":"第 101 轮发现 test_first_live_trade.py docstring 声称覆盖 _equity_stale 但只出现在 docstring 里","method":"AST 分离 docstring/code + 与真实行覆盖率交叉验证","first_version_flaws":["函数的 def 行在 import 时执行 -> 任何函数都显得测过（最要命，放过 21 个假阳性）","同名标识符跨模块冲突（klines 在 3 个模块各一份）","docstring 提到名字是为了说明它没被调用"],"final_result":{"true_positives":0,"candidates":3,"falsified":21},"candidates_all_false":{"ERROR":"散文词，源码匹配 aiohttp.WSMsgType.ERROR","check_risk_state":"docstring 说明它未被调用（准确定档）","klines":"同名冲突，未执行的是 feed.py:127 REST 兜底"},"verdict":"_equity_stale 是孤例，不是普遍现象。负结果，避免将来重跑","tool":"tools/docclaim.py（头部写明三个假阳性来源 + 真阳性数 0）","method_rule":"docstring 扫描只能产生假设，覆盖率才是验证；单独用任何一个都会撒谎","no_production_change":true,"tests_total":"499 全绿（仅重跑覆盖率，未改代码）","account_state":{"spot_usdt":0}}''')
J = Journal('data/market_trade.db')
J.start()
J.add('info', u'把「docstring 撒谎」做成机械扫描：真阳性 0 个，_equity_stale 是孤例',
      chr(10).join(L), json.dumps(meta, ensure_ascii=False))
print('journal ok')
J.stop()